 "content": "def transform(grid):
    """Encode the 3x3-cell marker mosaic as one color per tile."""
    rows, cols = len(grid), len(grid[0])
    out = []
    for r in range(0, rows, 3):
        out_row = []
        for c in range(0, cols, 3):
            marker = 0
            for rr in range(r, min(r + 3, rows)):
                for cc in range(c, min(c + 3, cols)):
                    value = grid[rr][cc]
                    if value not in (0, 5):
                        marker = value
                        break
                if marker:
                    break
            out_row.append(marker)
        out.append(out_row)
    return out

